package br.com.sussmartcare.clinicalquery.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="clinical_patient_views") public class ClinicalPatientView {@Id private UUID visitId;private UUID patientId;@Column(length=2000)private String preAnamnesis;private String journeyStatus;private String aiRecommendation;private Double aiConfidence;@Column(length=1200)private String aiReasoning;private String aiModelName;private String aiModelVersion;private String clinicalPriority;private String presenceStatus;private Integer queuePosition;private Integer estimatedMinutes;private String queueStatus;private String latestBiometricType;private Double latestBiometricValue;private String latestBiometricUnit;private String preArrivalRisk;private Instant preArrivalEta;@Column(nullable=false)private Instant updatedAt;protected ClinicalPatientView(){}public ClinicalPatientView(UUID visitId){this.visitId=visitId;updatedAt=Instant.now();}
 public void visit(UUID patient,String status){patientId=patient;journeyStatus=status;touch();} public void reassignPatient(UUID canonicalPatientId){patientId=canonicalPatientId;touch();} public void anamnesis(String text){preAnamnesis=text;touch();}public void biometric(UUID patient,String type,Double value,String unit){patientId=patient;latestBiometricType=type;latestBiometricValue=value;latestBiometricUnit=unit;touch();}public void assessment(String p,Double c,String r,String m,String mv){aiRecommendation=p;aiConfidence=c;aiReasoning=r;aiModelName=m;aiModelVersion=mv;touch();}public void priority(String p){clinicalPriority=p;journeyStatus="TRIAGED";touch();}public void presence(String p){presenceStatus=p;touch();}public void queue(Integer pos,Integer min,String status){queuePosition=pos;estimatedMinutes=min;queueStatus=status;journeyStatus="WAITING";touch();}public void preArrival(UUID patient,String risk,Instant eta){patientId=patient;preArrivalRisk=risk;preArrivalEta=eta;touch();}private void touch(){updatedAt=Instant.now();}
 public UUID getVisitId(){return visitId;}public UUID getPatientId(){return patientId;}public String getPreAnamnesis(){return preAnamnesis;}public String getJourneyStatus(){return journeyStatus;}public String getAiRecommendation(){return aiRecommendation;}public Double getAiConfidence(){return aiConfidence;}public String getAiReasoning(){return aiReasoning;}public String getAiModelName(){return aiModelName;}public String getAiModelVersion(){return aiModelVersion;}public String getClinicalPriority(){return clinicalPriority;}public String getPresenceStatus(){return presenceStatus;}public Integer getQueuePosition(){return queuePosition;}public Integer getEstimatedMinutes(){return estimatedMinutes;}public String getQueueStatus(){return queueStatus;}public String getLatestBiometricType(){return latestBiometricType;}public Double getLatestBiometricValue(){return latestBiometricValue;}public String getLatestBiometricUnit(){return latestBiometricUnit;}public String getPreArrivalRisk(){return preArrivalRisk;}public Instant getPreArrivalEta(){return preArrivalEta;}public Instant getUpdatedAt(){return updatedAt;}}
